-- ===========================================================================
-- Hand-written below.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One row only: Settings and Business.
--
-- `singleton` is unique, and these CHECKs hold it true, so a second row can
-- never be inserted: it would need a second value for a column that may only
-- be true. The services read the row by `singleton = true`.
-- ---------------------------------------------------------------------------
ALTER TABLE "Settings"
  ADD CONSTRAINT "Settings_singleton_check" CHECK ("singleton");

ALTER TABLE "Business"
  ADD CONSTRAINT "Business_singleton_check" CHECK ("singleton");

-- The ranges the staff app enforces, as a backstop for a write that does not
-- come through the route. Rates and money are never negative; the Free Table
-- Reminder is 15 to 1440 minutes (D37); times of day are minutes within one
-- day (1440 is midnight at its end); a lead time or slot step is positive.
ALTER TABLE "Settings"
  ADD CONSTRAINT "Settings_values_check" CHECK (
    "vatBps" >= 0
    AND "serviceBps" >= 0
    AND "depositKobo" >= 0
    AND "deliveryJosKobo" >= 0
    AND "deliveryOutsideKobo" >= 0
    AND "approvalLimitKobo" >= 0
    AND "dailyLimitKobo" >= 0
    AND "freeTableReminderMinutes" BETWEEN 15 AND 1440
    AND "lastArrivalMinutes" BETWEEN 0 AND 1440
    AND "lastOrderSlotMinutes" BETWEEN 0 AND 1440
    AND "slotStepMinutes" > 0
    AND "leadPickupMinutes" > 0
    AND "leadJosMinutes" > 0
    AND "leadOutsideMinutes" > 0
  );

-- ---------------------------------------------------------------------------
-- Opening hours: TAY's two CHECKs, copied.
--
-- 0 = Sunday … 6 = Saturday, JavaScript's getDay(). Closed: no times. Open:
-- both times, in WAT minutes from midnight, opening before closing, closing
-- no later than midnight at the end of the day (1440).
-- ---------------------------------------------------------------------------
ALTER TABLE "OpeningHoursDay"
  ADD CONSTRAINT "OpeningHoursDay_day_check"
  CHECK ("dayOfWeek" BETWEEN 0 AND 6);

ALTER TABLE "OpeningHoursDay"
  ADD CONSTRAINT "OpeningHoursDay_shape_check"
  CHECK (
    ("isClosed" AND "opensAtMinutes" IS NULL AND "closesAtMinutes" IS NULL)
    OR (
      NOT "isClosed"
      AND "opensAtMinutes" IS NOT NULL
      AND "closesAtMinutes" IS NOT NULL
      AND "opensAtMinutes" >= 0
      AND "opensAtMinutes" < "closesAtMinutes"
      AND "closesAtMinutes" <= 1440
    )
  );

-- The initial week (plan §4.1, D26; Q7's "08:00 to midnight every day").
-- Data only, and only into an empty table: `ON CONFLICT DO NOTHING` leaves a
-- week the Owner has already saved untouched. After this the week is changed
-- from the staff app, never by another migration. No AuditLog row: this is
-- the initial state, not anybody's action.
INSERT INTO "OpeningHoursDay" ("dayOfWeek", "updatedAt", "isClosed", "opensAtMinutes", "closesAtMinutes")
VALUES
  (0, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (1, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (2, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (3, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (4, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (5, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440),
  (6, CURRENT_TIMESTAMP AT TIME ZONE 'UTC', false, 480, 1440)
ON CONFLICT ("dayOfWeek") DO NOTHING;

