ALTER TABLE "Venue"
  ADD CONSTRAINT "Venue_values_check" CHECK ("bigParty" > 0);

ALTER TABLE "DiningTable"
  ADD CONSTRAINT "DiningTable_capacity_check" CHECK ("capacity" > 0);

-- A price is never negative. Zero is allowed (a complimentary item).
ALTER TABLE "MenuItem"
  ADD CONSTRAINT "MenuItem_price_check" CHECK ("priceKobo" >= 0);

-- ---------------------------------------------------------------------------
-- People.
--
-- Emails are stored lower case, so two spellings of one address cannot be two
-- accounts (the unique index is case-sensitive). A customer's phone is stored
-- in the one form the plan names, `0` plus 10 digits (canonicalNigerianPhone),
-- so `+2348031234567` and `08031234567` cannot be two customers. Both are
-- normalised by the service before the write; these refuse a write that
-- skipped it.
-- ---------------------------------------------------------------------------
ALTER TABLE "Staff"
  ADD CONSTRAINT "Staff_email_lower_check" CHECK ("email" = lower("email"));

ALTER TABLE "Customer"
  ADD CONSTRAINT "Customer_email_lower_check"
  CHECK ("email" IS NULL OR "email" = lower("email"));

ALTER TABLE "Customer"
  ADD CONSTRAINT "Customer_phone_format_check"
  CHECK ("phone" IS NULL OR "phone" ~ '^0[789][01][0-9]{8}$');

ALTER TABLE "OtpCode"
  ADD CONSTRAINT "OtpCode_attempts_check" CHECK ("attempts" >= 0);

-- ---------------------------------------------------------------------------
-- Stock items.
--
-- The name is unique ignoring case: the staff app refuses "rice" beside
-- "Rice" ("This stock item already exists."). Prisma cannot declare an index
-- on an expression, so it is created here. It is named `StockItem_name_key`,
-- Prisma's own pattern for a unique `name`, so `uniqueViolationTargets` reads
-- a clash as `["name"]` and the service can answer 409 with the domain's
-- sentence.
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX "StockItem_name_key" ON "StockItem" (lower("name"));

-- Whole conversions above zero and a non-negative reorder level, the staff
-- app's own rule ("Enter a whole conversion above zero and a non-negative
-- minimum.").
ALTER TABLE "StockItem"
  ADD CONSTRAINT "StockItem_values_check"
  CHECK ("factor" > 0 AND "minimum" >= 0);

-- A Bar stock item is exactly the paired stock of one Bar menu item, and a
-- Kitchen item has none (D45; the demo's `bar-<n>` ids were the menu ids).
-- With the unique index on "menuItemId", no menu item has two.
ALTER TABLE "StockItem"
  ADD CONSTRAINT "StockItem_pairing_check"
  CHECK (("kind" = 'BAR') = ("menuItemId" IS NOT NULL));

-- ---------------------------------------------------------------------------
-- The audit log is append-only (A13, D47).
--
-- A row trigger refuses every UPDATE and DELETE, and a statement trigger
-- refuses TRUNCATE, which bypasses row triggers. So no code path, mistaken
-- script or console session can rewrite history, and a foreign key that ever
-- tried to cascade into this table would fail rather than edit it (both of
-- its foreign keys restrict).
--
-- What this does not stop: the table's owner can drop or disable the
-- trigger. That is a deliberate schema change, made in a migration someone
-- reviews; the trigger is a guard against mistakes, not against the owner.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "audit_log_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'AuditLog is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "AuditLog_append_only_row"
  BEFORE UPDATE OR DELETE ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION "audit_log_append_only"();

CREATE TRIGGER "AuditLog_append_only_truncate"
  BEFORE TRUNCATE ON "AuditLog"
  FOR EACH STATEMENT EXECUTE FUNCTION "audit_log_append_only"();

-- An entry names the actor its kind says it has: a staff entry its staff
-- member, a customer entry its customer, and a system entry neither.
ALTER TABLE "AuditLog"
  ADD CONSTRAINT "AuditLog_actor_check" CHECK (
    ("actorKind" = 'STAFF' AND "staffId" IS NOT NULL AND "customerId" IS NULL)
    OR ("actorKind" = 'CUSTOMER' AND "customerId" IS NOT NULL AND "staffId" IS NULL)
    OR ("actorKind" = 'SYSTEM' AND "staffId" IS NULL AND "customerId" IS NULL)
  );

-- ---------------------------------------------------------------------------
-- Messages and idempotency.
-- ---------------------------------------------------------------------------
ALTER TABLE "OutboundMessage"
  ADD CONSTRAINT "OutboundMessage_attempts_check" CHECK ("attempts" >= 0);

-- ---------------------------------------------------------------------------
-- Human numbers: one sequence per prefix (A12, plan §4 "Sequences").
--
-- Drawn only through `nextSequenceCode` with the names in
-- src/prisma/sequences.ts, which says which prefix and digit count each one
-- carries. Each starts at 1, because no demo data is imported (Q11). A bulk
-- import that writes numbers without the sequence must re-seed it afterwards
-- with `SELECT setval('<name>', <highest number used>)`.
--
-- The tables most of these number (orders, payments, reservations…) arrive
-- in later cards; the sequences are created now so the list is in one place
-- and nothing has to remember to add one.
-- ---------------------------------------------------------------------------
CREATE SEQUENCE "order_restaurant_no_seq" AS bigint START WITH 1 NO CYCLE;   -- CNCR-000001
CREATE SEQUENCE "order_bar_no_seq" AS bigint START WITH 1 NO CYCLE;          -- CNCB-000001
CREATE SEQUENCE "online_order_no_seq" AS bigint START WITH 1 NO CYCLE;       -- WEB-000001
CREATE SEQUENCE "payment_no_seq" AS bigint START WITH 1 NO CYCLE;            -- PAY-000001
CREATE SEQUENCE "cash_count_no_seq" AS bigint START WITH 1 NO CYCLE;         -- CASH-000001
CREATE SEQUENCE "reservation_no_seq" AS bigint START WITH 1 NO CYCLE;        -- RSV-000001
CREATE SEQUENCE "stock_request_no_seq" AS bigint START WITH 1 NO CYCLE;      -- SR-000001
CREATE SEQUENCE "purchase_no_seq" AS bigint START WITH 1 NO CYCLE;           -- PR-000001
CREATE SEQUENCE "waste_no_seq" AS bigint START WITH 1 NO CYCLE;              -- W-000001
CREATE SEQUENCE "task_no_seq" AS bigint START WITH 1 NO CYCLE;               -- T-000001
CREATE SEQUENCE "maintenance_no_seq" AS bigint START WITH 1 NO CYCLE;        -- MT-000001
CREATE SEQUENCE "staff_no_seq" AS bigint START WITH 1 NO CYCLE;              -- CNC-S001
CREATE SEQUENCE "customer_member_no_seq" AS bigint START WITH 1 NO CYCLE;    -- CNC-000001
